def preserve_legacy_measurements(apps, schema_editor):
    RecipeIngredient = apps.get_model("seasonops", "RecipeIngredient")
    IngredientPurchaseLine = apps.get_model("seasonops", "IngredientPurchaseLine")

    for line in RecipeIngredient.objects.select_related("ingredient").iterator():
        line.unit = line.ingredient.unit
        line.save(update_fields=["unit"])

    for line in IngredientPurchaseLine.objects.select_related("ingredient").iterator():
        line.unit = line.ingredient.unit
        line.stock_quantity = line.quantity
        line.save(update_fields=["unit", "stock_quantity"])


def create_primary_locations(apps, schema_editor):
    Location = apps.get_model("seasonops", "Location")
    Location.objects.get_or_create(
        code="home-bakery",
        defaults={
            "name": "Home Bakery",
            "kind": "home_bakery",
            "is_active": True,
        },
    )
    Location.objects.get_or_create(
        code="cafe-sales",
        defaults={
            "name": "Café / Sales Location",
            "kind": "cafe",
            "is_active": True,
        },
    )


